import Foundation

// Port of the website's src/components/stories/usStateShapes.ts (Oct 21 2026): which US state a place is in, from its
// own coordinates. US Census Bureau state boundaries (2010, 1:5m, public domain), simplified to about 1 km and stored as
// encoded integer outlines (0.01 degree units). Same data string and the same tests as the website. No lookup service.

enum TravelerStateShapes {
    struct Ring {
        let xs: [Int]
        let ys: [Int]
        let x0: Int, y0: Int, x1: Int, y1: Int
    }
    struct Shape {
        let code: String
        let rings: [Ring]
    }

    private static func decode(_ s: String) -> [Int] {
        var out: [Int] = []
        let bytes = Array(s.utf8)
        var i = 0
        while i < bytes.count {
            var r = 0, sh = 0, b = 0
            repeat {
                b = Int(bytes[i]) - 63
                i += 1
                r |= (b & 0x1f) << sh
                sh += 5
            } while b >= 0x20 && i < bytes.count
            out.append(r & 1 != 0 ? ~(r >> 1) : r >> 1)
        }
        return out
    }

    /// Decoded once, on first use.
    static let shapes: [Shape] = {
        var list: [Shape] = []
        for part in data.split(separator: ";", omittingEmptySubsequences: false) {
            guard let k = part.firstIndex(of: ":") else { continue }
            let code = String(part[part.startIndex..<k])
            let body = part[part.index(after: k)...]
            var rings: [Ring] = []
            for enc in body.split(separator: ",", omittingEmptySubsequences: false) {
                let v = decode(String(enc))
                let n = v.count / 2
                var xs: [Int] = [], ys: [Int] = []
                xs.reserveCapacity(n)
                ys.reserveCapacity(n)
                var x = 0, y = 0, x0 = Int.max, y0 = Int.max, x1 = Int.min, y1 = Int.min
                for j in 0..<n {
                    x += v[2 * j]
                    y += v[2 * j + 1]
                    xs.append(x)
                    ys.append(y)
                    if x < x0 { x0 = x }
                    if x > x1 { x1 = x }
                    if y < y0 { y0 = y }
                    if y > y1 { y1 = y }
                }
                rings.append(Ring(xs: xs, ys: ys, x0: x0, y0: y0, x1: x1, y1: y1))
            }
            list.append(Shape(code: code, rings: rings))
        }
        return list
    }()

    private static func inside(_ r: Ring, _ x: Int, _ y: Int) -> Bool {
        if x < r.x0 || x > r.x1 || y < r.y0 || y > r.y1 { return false }
        var c = false
        let n = r.xs.count
        if n == 0 { return false }
        var j = n - 1
        for i in 0..<n {
            let yi = r.ys[i], yj = r.ys[j]
            if (yi > y) != (yj > y) {
                let cross = Double((r.xs[j] - r.xs[i]) * (y - yi)) / Double(yj - yi) + Double(r.xs[i])
                if Double(x) < cross { c.toggle() }
            }
            j = i
        }
        return c
    }

    /// Squared distance (0.01 degree units, longitude scaled by latitude) from a point to a ring's edge.
    private static func edgeDist2(_ r: Ring, _ x: Int, _ y: Int, _ kx: Double) -> Double {
        var best = Double.infinity
        let n = r.xs.count
        if n == 0 { return best }
        var j = n - 1
        let px = Double(x) * kx, py = Double(y)
        for i in 0..<n {
            let ax = Double(r.xs[j]) * kx, ay = Double(r.ys[j]), bx = Double(r.xs[i]) * kx, by = Double(r.ys[i])
            let dx = bx - ax, dy = by - ay, l = dx * dx + dy * dy
            let t = l != 0 ? max(0, min(1, ((px - ax) * dx + (py - ay) * dy) / l)) : 0
            let ex = ax + t * dx - px, ey = ay + t * dy - py
            let d = ex * ex + ey * ey
            if d < best { best = d }
            j = i
        }
        return best
    }

    /// The US state (two-letter code, or DC / PR) a point is in, or nil when it is outside the US.
    /// A point just off a simplified coast or border (within about 1.5 km) takes the nearest state.
    static func stateAt(_ lat: Double, _ lng: Double) -> String? {
        guard lat.isFinite, lng.isFinite else { return nil }
        let x = Int((lng * 100 + 0.5).rounded(.down)), y = Int((lat * 100 + 0.5).rounded(.down))
        let list = shapes
        for s in list { for r in s.rings where inside(r, x, y) { return s.code } }
        let kx = cos(lat * Double.pi / 180), lim = 1.4 * 1.4
        var best: String? = nil
        var bd = lim
        for s in list {
            for r in s.rings {
                if x < r.x0 - 4 || x > r.x1 + 4 || y < r.y0 - 2 || y > r.y1 + 2 { continue }
                let d = edgeDist2(r, x, y, kx)
                if d < bd { bd = d; best = s.code }
            }
        }
        return best
    }

